import{_ as t,o as a,c as p,a4 as _}from"./chunks/framework.C3unmAF4.js";const f=JSON.parse('{"title":"直播成为新农活，数据变成新农资——新农人蹚出兴农路2026-05-13","description":"","frontmatter":{"sidebar":false,"aside":false,"editLink":false,"lastUpdated":false,"prev":false,"next":false,"title":"直播成为新农活，数据变成新农资——新农人蹚出兴农路2026-05-13","date":"2026-05-13T00:00:00.000Z","source":"农业农村部市场与信息化司","category":"policies","link":"https://scs.moa.gov.cn/gzdt/202605/t20260513_6484131.htm","summary":"农民日报全媒体记者　张国凤\\n近年来,宁夏银川市金凤区从技术孵化、资金支持等全方位发力,培育了一批批乡村实用人才。如今,从技术革新到品牌升级,从单打独斗到联农共富,金凤区激活产业引擎,为乡土注入科技赋能、业态融合的时代活力,勾勒出农业强、农村美、农民富的现代化乡村新图景。\\n手机变农具,助农品“云”销四方\\n“炸油香,炸油香,好吃美味心间漾,咬一口来丢了魂,快来润丰尝一尝。...\\n","contentHash":"9f7c48ab64e88b5996d53845e89f7cd6","tags":["智慧农业","政策法规"]},"headers":[],"relativePath":"policies/2026-05-13-直播成为新农活-数据变成新农资-新农人蹚出兴农路.md","filePath":"policies/2026-05-13-直播成为新农活-数据变成新农资-新农人蹚出兴农路.md"}'),s={name:"policies/2026-05-13-直播成为新农活-数据变成新农资-新农人蹚出兴农路.md"};function r(o,e,n,c,l,i){return a(),p("div",null,[...e[0]||(e[0]=[_('<h1 id="直播成为新农活-数据变成新农资——新农人蹚出兴农路2026-05-13" tabindex="-1">直播成为新农活，数据变成新农资——新农人蹚出兴农路2026-05-13 <a class="header-anchor" href="#直播成为新农活-数据变成新农资——新农人蹚出兴农路2026-05-13" aria-label="Permalink to &quot;直播成为新农活，数据变成新农资——新农人蹚出兴农路2026-05-13&quot;">​</a></h1><blockquote><p>来源: <a href="https://scs.moa.gov.cn/gzdt/202605/t20260513_6484131.htm" target="_blank" rel="noreferrer">农业农村部市场与信息化司</a><br> 日期: 2026-05-13 摘要: 农民日报全媒体记者　张国凤 近年来,宁夏银川市金凤区从技术孵化、资金支持等全方位发力,培育了一批批乡村实用人才。如今,从技术革新到品牌升级,从单打独斗到联农共富,金凤区激活产业引擎,为乡土注入科技赋能、业态融合的时代活力,勾勒出农业强、农村美、农民富的现代化乡村新图景。 手机变农具,助农品“云”销四方 “炸油香,炸油香,好吃美味心间漾,咬一口来丢了魂,快来润丰尝一尝。...</p></blockquote><p>近年来,宁夏银川市金凤区从技术孵化、资金支持等全方位发力,培育了一批批乡村实用人才。如今,从技术革新到品牌升级,从单打独斗到联农共富,金凤区激活产业引擎,为乡土注入科技赋能、业态融合的时代活力,勾勒出农业强、农村美、农民富的现代化乡村新图景。</p><p>“炸油香,炸油香,好吃美味心间漾,咬一口来丢了魂,快来润丰尝一尝。”在直播间,金凤区丰登镇润丰村党支部书记王鹏程推介着油香、草莓、八宝茶等本村特色农产品,爽朗又活泼的吆喝声引得不少网友留言询问购买渠道。村民李大姐抱着一筐刚出锅的油香笑得合不拢嘴:“以前守着好东西卖不出去,现在跟着‘黑书记’做视频号,在家就能把货发往全国各地!”</p><p>“黑书记”是村民对王鹏程的昵称,“我日常工作就是跟村民打交道,要走街入户,要去田间地头,就晒得比较黑,所以大家经常叫我‘黑书记’。”王鹏程说。</p><p>润丰村作为移民搬迁村,近年来依托农业设施产业园区,不断引进各类企业,虽然实现了较为长足的发展,但壮大村集体经济的后劲始终跟不上,面对这一问题,作为村党支部书记的王鹏程下定决心,要让村子从“承包收租”全面转向“自主致富”。</p><p>随着全国各地掀起“局长宣传”“书记带货”的热潮,王鹏程发现了农文旅融合这一发展新招,于是他带头成立润腾旺丰农民农产品专业合作社,对自种温棚农产品进行市场化运营,打通包装、储存、运输等关键环节,不断延长产业链,提高农产品附加值;学习黄河民宿等区内先进文旅经验,盘活村部闲置资源,打造润丰宿集、野奢露营区等近郊旅游品牌;因地制宜申报“向往的润丰”导师帮带项目,邀请专业人士为村民培训视频拍摄、剪辑、直播技能,注册润丰村“黑书记”视频号,并成功认证为微信“三农博主”,截至目前,发布的“润丰故事”系列视频累计浏览量达50万人次,转发超过10万次,带动村民致富增收超过15万元。</p><p>好产品、好景色、好生活,润丰村的“美丽传说”越发广为人知,农文旅融合发展的振兴画卷正在徐徐展开。</p><p>除了油香,凉皮也是银川人民所喜爱的一道传统美食,通过特色化、品牌化的改造,金凤区良田镇“铁桥菊莲凉皮”便成为代表之一,成为乡村全面振兴的新引擎。</p><p>1996年,在良田镇的铁桥旁,一个不起眼的凉皮摊档支了起来。这个成本只有50元的摊档,在30年后,成长为年营收超千万元的特色品牌。“铁桥菊莲凉皮”创始人马菊莲用一碗凉皮书写了自己的创业传奇,更成为银川市统筹推进“两化一振兴”走深走实的生动注脚。</p><p>1991年,13岁的马菊莲随家人从固原市泾源县移民搬迁至如今的良田镇金星村。1996年,她拿着仅有的50元本金,在良田镇的铁桥旁支起凉皮摊。“我们从大山里搬出来,既然有了创业致富的机会,那就要努力拼一把,即使失败了,也不让自己留遗憾。”</p><p>没有技术、没有资金、没有设备,但马菊莲有一份决心。“那时候每天凌晨四五点起来和面、蒸面皮,六点就推着小车出摊。”马菊莲回忆。凭借独特的辣椒油配方和爽滑劲道的口感,她的凉皮很快赢得了街坊邻里的喜爱,摊前常常排起长队。</p><p>马菊莲的创业路,映照着宁夏移民妇女一步步努力奋斗的历程,也记录着党和政府对移民妇女创业的大力支持。“当时,铁桥那边还没有建房屋,我们的摊子就是支张桌子、围块布,风大的时候,沙子能直接吹进碗里。”马菊莲苦笑着说,当时想买个店面,但手头紧张只好作罢。2015年,良田镇妇联主动找到马菊莲,为她办理了3万元农村妇女创业贷款。马菊莲拿着这笔钱买了店面,告别了“路边摊时代”。此后不久,良田镇妇联再次帮助马菊莲贷款7万元,马菊莲用这7万元加上凑来的资金,购买了良田镇商业街上的营业房。</p><p>马菊莲有着更大的梦想,便是将自己的凉皮产业继续扩大,通过加盟、带动就业等方式,让更多人跟着自己走上致富之路。“她没有架子,有啥好吃的都会拿过来给我们尝尝。”一位在铁桥菊莲凉皮店干了10年的老员工说。马菊莲的凉皮加工厂、凉皮直营店都是优先雇佣周边村民,目前直接带动就业近百人,其中脱贫户占30%。</p><p>马菊莲还发起“凉皮师傅”培训计划,通过线上直播或线下教学方式,累计培养技能人才80余名。她还筹划建设电商直播基地,“我想让这碗凉皮走出宁夏,让更多人尝到咱银川良田镇的味道。”</p><p>从王鹏程大力发展短视频等新业态推动特色农产品打开销路,到传统手艺人马菊莲筹划建设电商直播基地让一碗凉皮飘香全国,让手机变成新农具、让直播变成新农活正激活产业发展新动能。而在良田镇光明村的鸿盛育苗基地负责人苏亚光,则用另一种方式诠释着新农人的使命——让数据变成新农资。</p><p>走进位于光明村的4000平方米智能联栋温室,5G传感器正将数据实时传至“育苗大脑”,每株苗都有定制化“营养套餐”。“只需扫码即可追溯72项生长数据,去年寒潮期间,智能温控系统使种苗损失率从往年的30%降至3%。”苏亚光一边展示自主研发的“穴盘身份证”,一边介绍道。</p><p>苏亚光是本土走出来的优秀青年大学生,2014年,他毅然放弃城市发展机遇,在家乡羊圈改造的实验室中开启了创业之路,凭借扎实的专业知识与不懈的实践探索,逐步攻克嫁接育苗技术难关。2020年,依托金凤区政府扶贫车间项目,他引进潮汐式苗床、温湿度联控系统,建成25栋智能化育苗大棚,将嫁接苗成活率提升至98%。2023年,他联合村党支部成立“创业园区”,将育苗技术拆解成57个标准化模块,通过“合作社+农户”模式,为126户村民提供技术培训与就业岗位,户均年增收3.6万元。</p><p>如今,苏亚光创立的鸿盛育苗基地将“云储存”“物联网”等新质生产力引入温室育苗当中,育苗量超2500万株,涵盖番茄、辣椒、西瓜等20余个品种,带动周边8000余亩设施农业升级,年产值突破1500万元,成为宁夏首个实现“种苗出口”的农业合作社,为乡村振兴注入强劲动能。</p><p><a href="https://scs.moa.gov.cn/gzdt/202605/t20260513_6484131.htm" target="_blank" rel="noreferrer">阅读原文</a></p>',20)])])}const m=t(s,[["render",r]]);export{f as __pageData,m as default};
